// Optional helper: try to find an interviewer link in the list_researches
// MCP output. Frank's exact JSON field names are not hard-coded here.
// Config and customer fields are read from the Set invite details node,
// because the MCP Client output replaces the previous item JSON.
const mcp = $input.item.json;
const cfg = $('Set invite details').item.json;
const fallback = typeof cfg.interviewLink === 'string' ? cfg.interviewLink : '';
const studyName = String(cfg.studyName || '').trim().toLowerCase();

function collect(value, bag, depth) {
  if (depth > 8 || value == null) return;
  if (typeof value === 'string') {
    bag.strings.push(value);
    const urlRe = /https?:\/\/[^\s"'<>\\)]+/g;
    const found = value.match(urlRe);
    if (found) bag.urls.push(...found);
    return;
  }
  if (Array.isArray(value)) {
    for (const entry of value) collect(entry, bag, depth + 1);
    return;
  }
  if (typeof value === 'object') {
    bag.objects.push(value);
    for (const key of Object.keys(value)) collect(value[key], bag, depth + 1);
  }
}

const bag = { strings: [], urls: [], objects: [] };
collect(mcp.structuredContent, bag, 0);
collect(mcp.content, bag, 0);
if (mcp.error) collect(mcp.error, bag, 0);

function objectText(obj) {
  try { return JSON.stringify(obj).toLowerCase(); } catch (e) { return ''; }
}

function urlsFromObject(obj) {
  const found = [];
  collect(obj, { strings: [], urls: found, objects: [] }, 0);
  return found;
}

let chosen = '';
if (studyName) {
  for (const obj of bag.objects) {
    const text = objectText(obj);
    if (!text.includes(studyName)) continue;
    const urls = urlsFromObject(obj);
    if (urls.length) {
      chosen = urls[0];
      break;
    }
  }
}
if (!chosen && bag.urls.length) {
  chosen = bag.urls[0];
}

const interviewLink = chosen || fallback;
return {
  json: {
    interviewLink,
    fromEmail: cfg.fromEmail,
    companyName: cfg.companyName,
    productName: cfg.productName,
    studyName: cfg.studyName,
    useFrankMcp: cfg.useFrankMcp,
    emailSubject: cfg.emailSubject,
    customerEmail: cfg.customerEmail,
    customerName: cfg.customerName,
    customerId: cfg.customerId,
    subscriptionId: cfg.subscriptionId,
    mcpLookupFound: Boolean(chosen),
    mcpLookupNote: mcp && mcp.error
      ? 'Frank MCP call did not succeed. Using the interviewLink from the configuration node.'
      : (chosen
        ? 'Used a URL found in the list_researches output. Confirm it is the interviewer link for your published study before going live.'
        : 'No URL found in the list_researches output. Using the interviewLink from the configuration node.'),
  },
};

